async function allow(redis: RedisClientType, key: string, limit: number): Promise<boolean> {
  const current = Number(await redis.get(key) ?? 0);
  if (current >= limit) {
    return false;
  }
  await redis.set(key, String(current + 1), { EX: 60 });
  return true;
}

