async function addNote(formData: FormData): Promise<void> {
  const text = String(formData.get('note'));
  addOptimisticNote(text);
  const saved = await postNote(orderId, text);
  setNotes((current) => [...current, saved]);
}

export default async function ProductPage({ params }: PageProps<'/products/[slug]'>) {
  const { slug } = await params;
  const product = await getProduct(slug);
  const stock = await getStock(slug);
  const reviews = await getReviews(slug);
  return <ProductView product={product} stock={stock} reviews={reviews} />;
}

