export async function cancelOrder(orderId: string): Promise<void> {
  const customer = await getCurrentCustomer();
  if (customer === null) {
    throw new Error('Unauthorized');
  }
  await ordersApi.cancel(orderId);
  updateTag('orders-' + customer.id);
}

